let max = typeof args.max_px === 'number' && args.max_px > 0 ? Math.min(args.max_px, 1920) : 1920;
let ancho = 1080;
let alto = 1920;

if (prop === '9:16') {
  alto = max;
  ancho = Math.round(max * 9 / 16);
} else if (prop === '1:1') {
  ancho = Math.min(max, 1080);
  alto = ancho;
} else if (prop === '16:9') {
  ancho = max;
  alto = Math.round(max * 9 / 16);
} else if (prop === '4:5') {
  alto = Math.min(max, 1350);
  ancho = Math.round(alto * 4 / 5);
} else {
  alto = max;
  ancho = Math.round(max * 9 / 16);
}

return {
  resolucion: `${ancho}x${alto}`
};

const prop = (args.proporcion || '9:16').trim();
const validos = ['9:16', '1:1', '3:4', '4:3', '16:9'];
if (validos.includes(prop)) {
  return { aspect_ratio_gemini: prop };
}
if (prop === '4:5') {
  return { aspect_ratio_gemini: '3:4' };
}
return { aspect_ratio_gemini: '9:16' };

if (!args.concepto || typeof args.concepto !== 'string') {
  throw new Error("El concepto es requerido.");
}
const concepto = args.concepto.trim();
const estilo = (args.estilo || 'lifestyle').toLowerCase().trim();

let mod = "estilo Instagram lifestyle, iluminacion natural suave, composicion cuidada, alta definicion";
if (estilo === 'cinematic') {
  mod = "estilo cinematografico, iluminacion dramatica, profundidad de campo, alta resolucion 8k";
} else if (estilo === 'minimalist') {
  mod = "estilo minimalista contemporaneo, composicion limpia, tonos suaves, estetica moderna";
}

return {
  prompt_final: `${concepto}. ${mod}.`
};

if (!args.prompt || typeof args.prompt !== 'string' || !args.prompt.trim()) {
  throw new Error("El parámetro 'prompt' es requerido.");
}
const apiKey = ctx.env.GEMINI_API_KEY;
if (!apiKey) {
  return { exito: false, error: "Falta GEMINI_API_KEY: configúrala en Ajustes → Claves y variables (AGENT_BANANO_GEMINI_API_KEY o GEMINI_API_KEY)." };
}

// Ratios que acepta la API de imágenes de Gemini
const validos = ['1:1', '2:3', '3:2', '3:4', '4:3', '4:5', '5:4', '9:16', '16:9', '21:9'];
let ratio = String(args.aspect_ratio || '9:16').trim();
if (!validos.includes(ratio)) ratio = '9:16';

const modelo = String(args.modelo || 'gemini-3.1-flash-image').trim();
const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(modelo)}:generateContent`;
const body = {
  contents: [{ parts: [{ text: args.prompt.trim() }] }],
  generationConfig: { responseModalities: ['IMAGE'], imageConfig: { aspectRatio: ratio } }
};

const res = await ctx.fetch(endpoint, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'x-goog-api-key': apiKey },
  body: JSON.stringify(body)
});

if (!res.ok) {
  const msg = (res.json && res.json.error && res.json.error.message) ? res.json.error.message : `HTTP ${res.status}`;
  return { exito: false, status: res.status, modelo, error: `Gemini no pudo generar la imagen: ${msg}` };
}

const parts = (((res.json || {}).candidates || [])[0] || {}).content ? res.json.candidates[0].content.parts || [] : [];
const img = parts.find(p => p.inlineData && p.inlineData.data);
if (!img) {
  const texto = parts.map(p => p.text).filter(Boolean).join(' ').slice(0, 300);
  const bloqueo = res.json && res.json.promptFeedback && res.json.promptFeedback.blockReason;
  return { exito: false, modelo, error: bloqueo ? `Gemini bloqueó el prompt (${bloqueo})` : 'Gemini no devolvió imagen', detalle: texto };
}

const mime = img.inlineData.mimeType || 'image/png';
const ext = mime.includes('jpeg') ? 'jpg' : mime.includes('webp') ? 'webp' : 'png';
const nombre = `banano-${ratio.replace(':', 'x')}-${Date.now()}.${ext}`;
return {
  exito: true,
  modelo,
  aspect_ratio: ratio,
  prompt_usado: args.prompt.trim(),
  adjuntos: [{ tipo: 'imagen', mime, base64: img.inlineData.data, nombre, caption: args.caption || undefined }]
};
